detector_raw:
{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of this production plan — are we maximizing total profit (unit price minus raw material cost minus processing cost), or is there another goal such as maximizing total output or minimizing total cost?"
  ],
  "rationale": "The response asks for a single policy choice regarding the optimization objective, presenting mutually exclusive options within one sentence."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are there any demand limits or minimum production requirements for each product, or can we produce any non-negative quantity of each product as long as equipment capacity allows?"
  ],
  "rationale": "The response asks a single clarification question regarding the existence of demand limits or minimum production requirements versus the ability to produce any non-negative quantity."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "For the processing cost, is the cost per machine hour applied to the actual processing time used (i.e., cost = processing time per unit × number of units × rate per hour), so that the total processing cost for a product on a given equipment equals the number of units times the processing time per unit times the hourly rate?"
  ],
  "rationale": "The response contains a single clarification question asking for confirmation of the specific formula used to calculate processing costs."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "is it allowed to split the production of a single product across different equipment types within the same stage, or must all units of a given product use the same equipment type for each stage?"
  ],
  "rationale": "The response asks for a single policy decision regarding whether production can be split across equipment types within a stage."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "For the flow balance between stages, does the total number of units of each product processed in stage A have to exactly equal the total number of units processed in stage B (i.e., no work-in-progress or inventory carried between stages), or could some units be left unfinished at the end of the planning period?"
  ],
  "rationale": "The response asks a single clarification question regarding the flow balance constraints between stages, specifically whether units must match exactly or if work-in-progress is allowed."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are the processing times in the table (e.g., 5 hours for Product I on A1) the time required per single unit of product, so that producing x units on A1 would consume 5x machine hours?"
  ],
  "rationale": "The response contains a single clarification question asking for confirmation of the unit basis for the processing times."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are there any other constraints or considerations I should be aware of, such as setup times, minimum batch sizes, or labor constraints, or is the model fully defined by the equipment capacity limits, the stage flow balance, and the profit objective?"
  ],
  "rationale": "The response contains a single compound question asking whether additional constraints exist or if the current definition is complete. This requires one policy/status confirmation from the user."
}
